# MathDB 336197 / Haslegrave Conjecture 2: every graph with m edges and no isolated edge has a bijection
# E->[m] whose vertex sums distinguish all pairs at distance <=2. Sweep all graphs on <=N vertices
# (up to isomorphism, generated by vertex extension; canonical form = min adjacency code over
# degree-respecting permutations). Isolated vertices are irrelevant (they are at distance >2 from all others),
# so graphs with isolated vertices are skipped; graphs with an isolated edge (K2 component) are excluded.
import sys,itertools,random,json,time
N=int(sys.argv[1])
def canon(n,adj):
    deg=[bin(a).count('1') for a in adj]
    # refine: key = (deg, sorted neighbor degrees)
    key=[(deg[v],tuple(sorted(deg[u] for u in range(n) if adj[v]>>u&1))) for v in range(n)]
    groups={}
    for v in range(n): groups.setdefault(key[v],[]).append(v)
    order=sorted(groups)
    best=None
    for combo in itertools.product(*[itertools.permutations(groups[k]) for k in order]):
        perm=[v for g in combo for v in g]  # perm[i]=old vertex at new position i
        pos={v:i for i,v in enumerate(perm)}
        code=tuple(sorted((min(pos[u],pos[v]),max(pos[u],pos[v])) for v in range(n) for u in range(v+1,n) if adj[v]>>u&1))
        code=(tuple(sorted(key)),code)
        if best is None or code<best: best=code
    return best
def extend(classes,n):
    out={}
    for adj in classes:
        for nb in range(1<<n):
            a=list(adj)+[nb]
            for v in range(n):
                if nb>>v&1: a[v]|=1<<n
            c=canon(n+1,a)
            if c not in out: out[c]=tuple(a)
    return list(out.values())
def ok_graph(n,adj):
    if any(a==0 for a in adj): return False
    for v in range(n):
        if bin(adj[v]).count('1')==1:
            u=adj[v].bit_length()-1
            if bin(adj[u]).count('1')==1: return False  # isolated edge
    return True
def solve(n,adj,rng,tries=300,steps=3000):
    edges=[(u,v) for v in range(n) for u in range(v) if adj[v]>>u&1]; m=len(edges)
    inc=[[i for i,e in enumerate(edges) if v in e] for v in range(n)]
    close=[]
    for v in range(n):
        two=adj[v]
        for u in range(n):
            if adj[v]>>u&1: two|=adj[u]
        two&=~(1<<v)
        close+=[(v,u) for u in range(v+1,n) if two>>u&1]
    def conflicts(lab):
        S=[sum(lab[i] for i in inc[v]) for v in range(n)]
        return [p for p in close if S[p[0]]==S[p[1]]]
    for t in range(tries):
        lab=list(range(1,m+1)); rng.shuffle(lab)
        c=conflicts(lab)
        for s in range(steps):
            if not c: return lab
            v,u=rng.choice(c); i=rng.choice(inc[v]+inc[u]); j=rng.randrange(m)
            lab[i],lab[j]=lab[j],lab[i]
            c2=conflicts(lab)
            if len(c2)<=len(c) or rng.random()<0.03: c=c2
            else: lab[i],lab[j]=lab[j],lab[i]
    return None
rng=random.Random(7); classes=[(0,)]; t0=time.time()
for n in range(1,N):
    classes=extend(classes,n)
    good=[a for a in classes if ok_graph(n+1,a)]
    fails=[]
    for a in good:
        lab=solve(n+1,a,rng)
        if lab is None: fails.append(a)
    print(json.dumps(dict(n=n+1,classes=len(classes),tested=len(good),fails=[list(f) for f in fails][:10],sec=round(time.time()-t0,1))),flush=True)
